//go:build riscv64

package gf65536

import "golang.org/x/sys/cpu"

// RVV kernels (vrgather.vv split tables) generated by go-asmgen
// (gen/galois_riscv64_gen.go) into galois_riscv64.s. The V instructions trap on
// a hart without the vector extension, so the tier is offered only when present.
func galMulRVV(dst, src []byte, tbl *[128]byte, n int)
func galMulAddRVV(dst, src []byte, tbl *[128]byte, n int)

func archTiers() (t []tier) {
	if cpu.RISCV64.HasV {
		t = append(t, blockTier("rvv", galMulRVV, galMulAddRVV))
	}
	return t
}
